class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n, m = len(nums), len(pattern)
        s = [(nums[i+1] > nums[i]) - (nums[i+1] < nums[i]) for i in range(n - 1)]
        return sum(s[i:i+m] == pattern for i in range(len(s) - m + 1))

