class Solution {
public:
    int countMatchingSubarrays(vector<int>& nums, vector<int>& pattern) {
        int n = nums.size(), m = pattern.size(), ans = 0;
        vector<int> s(n - 1);
        for (int i = 0; i + 1 < n; i++)
            s[i] = nums[i+1] > nums[i] ? 1 : (nums[i+1] < nums[i] ? -1 : 0);
        for (int i = 0; i + m <= n - 1; i++) {
            bool ok = true;
            for (int k = 0; k < m && ok; k++) ok = s[i+k] == pattern[k];
            ans += ok;
        }
        return ans;
    }
};

