class Solution {
    public int countMatchingSubarrays(int[] nums, int[] pattern) {
        int n = nums.length, m = pattern.length, ans = 0;
        int[] s = new int[n - 1];
        for (int i = 0; i + 1 < n; i++)
            s[i] = Integer.compare(nums[i+1], nums[i]);
        for (int i = 0; i + m <= n - 1; i++) {
            boolean ok = true;
            for (int k = 0; k < m; k++) if (s[i+k] != pattern[k]) { ok = false; break; }
            if (ok) ans++;
        }
        return ans;
    }
}

