var countMatchingSubarrays = function(nums, pattern) {
    const n = nums.length, m = pattern.length;
    const s = [];
    for (let i = 0; i + 1 < n; i++)
        s.push(Math.sign(nums[i+1] - nums[i]));
    let ans = 0;
    for (let i = 0; i + m <= s.length; i++) {
        let ok = true;
        for (let k = 0; k < m; k++) if (s[i+k] !== pattern[k]) { ok = false; break; }
        if (ok) ans++;
    }
    return ans;
};
